internal static class WorkspaceChecks
{
    private sealed class NetworkState{internal int Calls,Active,Maximum,Failures;internal bool Wait;}
    private sealed class FakeHttp(NetworkState state) : HttpMessageHandler
    {
        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)
        {
            Interlocked.Increment(ref state.Calls);int active=Interlocked.Increment(ref state.Active);state.Maximum=Math.Max(state.Maximum,active);
            try{if(state.Wait)await Task.Delay(Timeout.Infinite,ct);await Task.Delay(20,ct);if(state.Failures>0){state.Failures--;return new(HttpStatusCode.ServiceUnavailable){RequestMessage=request,Content=new StringContent("fixture")};}return new(HttpStatusCode.OK){RequestMessage=request,Content=new ByteArrayContent(new byte[]{1,2,3,4})};}finally{Interlocked.Decrement(ref state.Active);}
        }
    }
    private sealed class NoNetwork : HttpMessageHandler
    {
        internal int Calls;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;throw new Exception("Offline mode attempted network access");}
    }
    internal static void Run(bool ui)
    {
        int checks=0;void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;}
        void Reject(Action work){try{work();}catch(Exception ex)when(ex is IOException or InvalidDataException or ArgumentException or OperationCanceledException or HttpRequestException){checks++;return;}throw new Exception("Invalid workspace operation accepted");}
        string folder=Path.Combine(Path.GetTempPath(),"PlaySpaceWorkspaceChecks-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string prior=Workspace.ActiveFolder;Workspace.Use(folder);
        var game=new GameInfo{Name="Demo One",ExePath=Path.Combine(folder,"game.exe"),SteamAppId="620"};File.WriteAllText(game.ExePath,"fixture-not-executable");var other=new GameInfo{Name="Demo Two",ExePath="steam://rungameid/123",SteamAppId="123"};GameLibraryStore.Save(Path.Combine(folder,"games.json"),new(){game,other});
        var collections=Workspace.Current.Collections;collections.Create("Пройти");collections.Set(game.LibraryId,"Пройти",true);Check(collections.Contains(game,"Пройти")&&!collections.Contains(other,"Пройти"),"Collection membership incorrect");collections.Rename("Пройти","На выходные");Check(collections.Contains(game,"На выходные")&&!collections.Contains(game,"Пройти"),"Collection rename lost membership");Check(new LibraryCollections(folder).Contains(game,"На выходные"),"Collection persistence failed");Reject(()=>collections.Create("НА ВЫХОДНЫЕ"));Reject(()=>collections.Create("bad\nname"));Reject(()=>collections.Set("../bad","На выходные",true));collections.Remove("На выходные");Check(!collections.Contains(game,"На выходные")&&File.Exists(game.ExePath),"Removing collection touched game files");collections.Create("Кооп");collections.Set(game.LibraryId,"Кооп",true);
        var history=Workspace.Current.History;history.Add(game,"Моды","Installed fixture mod");var rediscovered=new GameInfo{Name=game.Name,ExePath=game.ExePath,SteamAppId=game.SteamAppId};history.Add(rediscovered,"Настройки","Changed fixture graphics");Check(history.Entries().Count==2&&history.Entries().All(e=>e.GameId==game.LibraryId),"History didn't bind rediscovered game to library identity");
        var commands=Enumerable.Range(0,200).Select(i=>new LauncherCommand("Game "+i,"Играть",()=>{})).Append(new LauncherCommand("Моды и наборы","Раздел",()=>{})).ToArray();Check(CommandPalette.Find(commands,"  game 199 ").Length==1,"Palette couldn't find game outside initial page");Check(CommandPalette.Find(commands,"").Length==80,"Palette result limit missing");Check(CommandPalette.Find(commands,"наборы").Single().Category=="Раздел","Palette command search failed");
        var state=new NetworkState();bool offline=false;var center=new TransferCenter(Path.Combine(folder,"downloads"),()=>new HttpClient(new FakeHttp(state)),()=>offline);
        Task.Run(async()=>{var first=center.Fetch("Fixture A",new Uri("https://example.com/a"),100,default);var second=center.Fetch("Fixture B",new Uri("https://example.com/b"),100,default);await Task.WhenAll(first,second);}).GetAwaiter().GetResult();Check(state.Maximum==1&&center.Items().Count==2&&center.Items().All(j=>j.State==TransferState.Completed),"Transfer queue isn't serialized");
        int before=state.Calls;offline=true;Check(center.Fetch("Cached",new Uri("https://example.com/a"),100,default).GetAwaiter().GetResult().Length==4&&state.Calls==before,"Offline transfer cache not used");Reject(()=>center.Fetch("Not cached",new Uri("https://example.com/c"),100,default).GetAwaiter().GetResult());Check(state.Calls==before,"Offline transfer made network request");offline=false;
        state.Failures=1;Reject(()=>center.Fetch("Retry fixture",new Uri("https://example.com/retry"),100,default).GetAwaiter().GetResult());string failed=center.Items().First().Id;center.Retry(failed).GetAwaiter().GetResult();Check(center.Items().Single(j=>j.Id==failed).State==TransferState.Completed,"Transfer retry failed");
        state.Wait=true;var pending=center.Fetch("Cancel fixture",new Uri("https://example.com/cancel"),100,default);string cancelId=center.Items().First().Id;var queued=center.Fetch("Cancel queued fixture",new Uri("https://example.com/queued"),100,default);string queuedId=center.Items().First().Id;Reject(()=>center.ClearCache());center.Cancel(queuedId);Reject(()=>queued.GetAwaiter().GetResult());center.Cancel(cancelId);Reject(()=>pending.GetAwaiter().GetResult());state.Wait=false;Check(center.Items().Single(j=>j.Id==cancelId).State==TransferState.Cancelled&&center.Items().Single(j=>j.Id==queuedId).State==TransferState.Cancelled,"Transfer cancellation not recorded");Reject(()=>center.Fetch("Too big",new Uri("https://example.com/big"),2,default).GetAwaiter().GetResult());Reject(()=>center.Fetch("Unsafe",new Uri("http://example.com/unsafe"),100,default));Check(center.CacheSize()>0,"Transfer cache size missing");center.ClearCache();Check(center.CacheSize()==0,"Transfer cache clear failed");
        string root=Path.Combine(folder,"mod-game");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"game.exe"),"original game");var installer=new ModInstaller(root);
        ModSelection Mod(string name)=>new(new ModPackage{Owner="Fixture",Name=name},new ModVersion{Version="1.0.0"});
        installer.Apply(new(){(Mod("One"),new Dictionary<string,byte[]>{{"mods/one.dll",new byte[]{1}}})},new Progress<string>());var profiles=new ModProfileStore(root,()=>{});var one=profiles.Save("Кооператив");Check(profiles.List().Count==1,"Managed profile wasn't saved");profiles.Activate(null);Check(!File.Exists(Path.Combine(root,"mods","one.dll"))&&installer.ReadState().Packages.Count==0&&File.ReadAllText(Path.Combine(root,"game.exe"))=="original game","Without-mods mode touched original game or left owned files");
        installer.Apply(new(){(Mod("Two"),new Dictionary<string,byte[]>{{"mods/two.dll",new byte[]{2}}})},new Progress<string>());var two=profiles.Save("Другая сборка");profiles.Activate(one.Id);Check(File.Exists(Path.Combine(root,"mods","one.dll"))&&!File.Exists(Path.Combine(root,"mods","two.dll"))&&installer.ReadState().Packages.ContainsKey("Fixture-One"),"Managed profile switch failed");Reject(()=>profiles.Activate(two.Id,n=>throw new IOException("Fixture switch error")));Check(File.Exists(Path.Combine(root,"mods","one.dll"))&&installer.ReadState().Packages.ContainsKey("Fixture-One")&&!File.Exists(Path.Combine(root,".playspace-mods","profile-switch.json")),"Profile rollback failed");
        string profileFile=Path.Combine(root,".playspace-mods","profiles",one.Id,"profile.json"),original=File.ReadAllText(profileFile);var invalid=JObject.Parse(original);invalid["State"]!["Packages"]!["Fixture-One"]!["Dependencies"]=new JArray("Missing-Mod-1.0.0");File.WriteAllText(profileFile,invalid.ToString());Reject(()=>profiles.Activate(one.Id));File.WriteAllText(profileFile,original);
        profiles.Activate(null);Directory.CreateDirectory(Path.Combine(root,"mods"));File.WriteAllText(Path.Combine(root,"mods","one.dll"),"external mod");Reject(()=>profiles.Activate(one.Id));Check(File.ReadAllText(Path.Combine(root,"mods","one.dll"))=="external mod","Profile overwrote unowned file");File.Delete(Path.Combine(root,"mods","one.dll"));profiles.Activate(one.Id);
        File.WriteAllBytes(Path.Combine(root,".playspace-mods","profiles",one.Id,"files","mods","one.dll"),new byte[]{9});Reject(()=>profiles.Activate(one.Id));Check(File.ReadAllBytes(Path.Combine(root,"mods","one.dll"))[0]==1,"Corrupt profile changed active files");
        var beforeCrash=installer.ReadState();string transaction=Guid.NewGuid().ToString("N"),backup=Path.Combine(root,".playspace-mods","profile-transactions",transaction,"mods","one.dll");Directory.CreateDirectory(Path.GetDirectoryName(backup)!);File.Copy(Path.Combine(root,"mods","one.dll"),backup);string oldHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(backup)));LocalJson.Write(Path.Combine(root,".playspace-mods","profile-switch.json"),new{Id=transaction,Before=beforeCrash,Changes=new[]{new{Path="mods/one.dll",Before=oldHash,After=(string?)null}}});File.Delete(Path.Combine(root,"mods","one.dll"));Check(installer.ReadState().Packages.ContainsKey("Fixture-One")&&File.Exists(Path.Combine(root,"mods","one.dll")),"Pending profile switch wasn't recovered by ordinary mod manager");
        profiles.Activate(null);File.WriteAllBytes(Path.Combine(root,"shared.dll"),new byte[]{3});installer.Apply(new(){(Mod("Shared"),new Dictionary<string,byte[]>{{"shared.dll",new byte[]{3}}})},new Progress<string>());var shared=profiles.Save("Общая библиотека");profiles.Activate(null);Check(File.Exists(Path.Combine(root,"shared.dll")),"Without-mods profile removed pre-existing shared file");profiles.Activate(shared.Id);Check(installer.ReadState().Packages.ContainsKey("Fixture-Shared"),"Profile couldn't reuse shared original library");
        var movement=new ControllerNavigation();Check(movement.Update(0x1000,0).Contains(ControllerAction.Launch)&&!movement.Update(0x1000,100).Contains(ControllerAction.Launch),"Held gamepad A launches repeatedly");movement.Update(0,110);Check(movement.Update(0x3000,120).SequenceEqual(new[]{ControllerAction.Back}),"Back didn't take priority over launch");movement.Update(0,130);Check(movement.Update(8,140).Contains(ControllerAction.Right)&&movement.Update(8,200).Length==0&&movement.Update(8,400).Contains(ControllerAction.Right),"Gamepad navigation repeat timing incorrect");
        var preferences=new LauncherPreferences{OfflineMode=true,AccentName="Мятный",TextScalePercent=120,PosterWidth=240,ReduceMotion=true};preferences.Save(folder);PresentationOptions.Configure(preferences);Check(PresentationOptions.ReduceMotion&&PresentationOptions.PosterWidth==240&&Math.Abs(PresentationOptions.TextScale-1.2)<0.01&&VisualTheme.Accent==PresentationOptions.Accents["Мятный"],"Appearance settings weren't applied");
        if(ui){
            var flags=BindingFlags.Instance|BindingFlags.NonPublic;IEnumerable<Control> Children(Control parent)=>parent.Controls.Cast<Control>().SelectMany(child=>new[]{child}.Concat(Children(child)));
            using(var form=new CollectionsForm(new[]{game,other},collections)){form.Show();Application.DoEvents();Check(Children(form).OfType<CheckedListBox>().Single().Items.Count==2,"Collections UI missing library");}
            using(var form=new DownloadsForm(center)){form.Show();Application.DoEvents();Check(Children(form).OfType<ListBox>().Single().Items.Count>0,"Downloads UI missing queue");}
            using(var form=new ActivityHistoryForm(new[]{game,other},history,game)){form.Show();Application.DoEvents();Check(Children(form).OfType<FormattedDescription>().Single().Text.Contains("fixture"),"History UI missing events");}
            using(var form=new NowPlayingForm(()=>new[]{new PlayingGame(game,TimeSpan.FromMinutes(12))},g=>{},g=>{})){form.Show();Application.DoEvents();Check(Children(form).OfType<FormattedDescription>().Single().Text.Contains("00:12:00"),"Current-session card missing elapsed time");}
            using(var form=new ControllerLibraryForm(new[]{game,other},collections,g=>Task.FromResult<Bitmap?>(null),()=>null,false)){form.Show();Application.DoEvents();form.Apply(ControllerAction.Right);form.Apply(ControllerAction.Launch);Check(ReferenceEquals(form.LaunchRequested,other),"Controller mode launched wrong selection");}
            string cache=Path.Combine(folder,"store-details");Directory.CreateDirectory(cache);string shotUrl="https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/620/ss_fixture.jpg";string shot=Path.Combine(cache,"screenshots","620-"+Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(shotUrl)))[..16]+".jpg");Directory.CreateDirectory(Path.GetDirectoryName(shot)!);using(var image=new Bitmap(20,10))image.Save(shot,System.Drawing.Imaging.ImageFormat.Jpeg);File.WriteAllText(Path.Combine(cache,"620.json"),new JObject{["detailed_description"]="<p>Offline saved description</p>",["screenshots"]=new JArray(new JObject{["path_full"]=shotUrl})}.ToString());using var blocked=new NoNetwork();using var client=new HttpClient(blocked);using(var form=new RecommendationsForm(folder,g=>Task.FromResult<Bitmap?>(null),client,"620")){form.Show();Application.DoEvents();var description=(FormattedDescription)typeof(RecommendationsForm).GetField("description",flags)!.GetValue(form)!;var deadline=DateTime.UtcNow.AddSeconds(2);while(!description.Text.Contains("Offline saved description")&&DateTime.UtcNow<deadline){Application.DoEvents();Thread.Sleep(5);}Check(description.Text.Contains("Offline saved description")&&blocked.Calls==0,"Offline recommendations attempted network or ignored cache");Check(((PictureBox)typeof(RecommendationsForm).GetField("banner",flags)!.GetValue(form)!).Image!=null&&blocked.Calls==0,"Offline screenshot cache not used");}
            using(var main=new Form1(folder)){main.Show();main.Size=main.MinimumSize;Application.DoEvents();Check(Children(main).OfType<ModernButton>().Single(button=>button.Text=="Моё пространство").Visible,"Workspace navigation clipped at minimum size");var actions=(IReadOnlyList<LauncherCommand>)typeof(Form1).GetMethod("WorkspaceCommands",flags)!.Invoke(main,null)!;Check(actions.Count>=9,"Workspace sections missing");using var form=new WorkspaceForm(actions);form.Show();Application.DoEvents();Directory.CreateDirectory("artifacts");using var screenshot=new Bitmap(form.Width,form.Height);form.DrawToBitmap(screenshot,form.ClientRectangle);screenshot.Save("artifacts/workspace-preview.png");}
        }
        Workspace.Use(prior);PresentationOptions.Configure(new LauncherPreferences());Console.WriteLine($"PASS: {checks} workspace checks: queued transfers/cache/retry/cancel, mod profiles/dependencies/rollback/ownership, collections/history, palette, controller input, appearance and offline data"+(ui?", UI":"")+". Fixtures only; no real games, network requests or installations.");
    }
}
